  ('excited-adjective', 'excited', 'adjective', '/ɪkˈsaɪtɪd/', 'hào hứng', 'very happy and enthusiastic', 'We are excited about the trip.', 'Chúng tôi rất háo hức về chuyến đi.', 'A2', 'emotions'),
  ('embarrassed-adjective', 'embarrassed', 'adjective', '/ɪmˈbærəst/', 'xấu hổ, ngượng', 'feeling shy or uncomfortable in front of others', 'I was embarrassed when I forgot his name.', 'Tôi xấu hổ khi quên tên anh ấy.', 'B1', 'emotions'),
  ('confident-adjective', 'confident', 'adjective', '/ˈkɑːnfɪdənt/', 'tự tin', 'sure about your own abilities', 'Practice helps you feel confident.', 'Luyện tập giúp bạn thấy tự tin.', 'B1', 'emotions'),
  ('frustrated-adjective', 'frustrated', 'adjective', '/ˈfrʌstreɪtɪd/', 'bực bội, nản', 'annoyed because you cannot do what you want', 'I get frustrated when the internet is slow.', 'Tôi bực mình khi mạng chậm.', 'B1', 'emotions'),
  ('apologize-verb', 'apologize', 'verb', '/əˈpɑːlədʒaɪz/', 'xin lỗi', 'to say you are sorry', 'He apologized for being late.', 'Anh ấy xin lỗi vì đến muộn.', 'B1', 'emotions'),
  ('persuade-verb', 'persuade', 'verb', '/pərˈsweɪd/', 'thuyết phục', 'to make someone agree to do something', 'She persuaded me to join the club.', 'Cô ấy thuyết phục tôi tham gia câu lạc bộ.', 'B2', 'emotions'),
  ('overwhelmed-adjective', 'overwhelmed', 'adjective', '/ˌoʊvərˈwelmd/', 'choáng ngợp, quá tải', 'feeling that you have too much to deal with', 'I felt overwhelmed in my first week at work.', 'Tôi thấy quá tải trong tuần đầu đi làm.', 'B2', 'emotions'),
  ('empathy-noun', 'empathy', 'noun', '/ˈempəθi/', 'sự đồng cảm', 'the ability to understand other people’s feelings', 'Good teachers show empathy for their students.', 'Giáo viên giỏi luôn đồng cảm với học sinh.', 'C1', 'emotions'),
  ('price-noun', 'price', 'noun', '/praɪs/', 'giá', 'the amount of money something costs', 'What’s the price of this shirt?', 'Chiếc áo này giá bao nhiêu?', 'A1', 'business'),
  ('customer-noun', 'customer', 'noun', '/ˈkʌstəmər/', 'khách hàng', 'a person who buys goods or services', 'The customer asked for a refund.', 'Khách hàng yêu cầu hoàn tiền.', 'A2', 'business'),
  ('discount-noun', 'discount', 'noun', '/ˈdɪskaʊnt/', 'sự giảm giá', 'a reduction in the usual price', 'Students get a 10% discount.', 'Sinh viên được giảm giá 10%.', 'A2', 'business'),
  ('invoice-noun', 'invoice', 'noun', '/ˈɪnvɔɪs/', 'hóa đơn', 'a document asking for payment for goods or services', 'Please send the invoice by email.', 'Vui lòng gửi hóa đơn qua email.', 'B1', 'business'),
  ('budget-noun', 'budget', 'noun', '/ˈbʌdʒɪt/', 'ngân sách', 'a plan for how to spend money', 'We need to stay within budget.', 'Chúng ta cần chi tiêu trong ngân sách.', 'B1', 'business'),
  ('profit-noun', 'profit', 'noun', '/ˈprɑːfɪt/', 'lợi nhuận', 'money you earn after costs are paid', 'The company made a small profit this year.', 'Năm nay công ty có lãi một chút.', 'B1', 'business'),
  ('revenue-noun', 'revenue', 'noun', '/ˈrevənuː/', 'doanh thu', 'the total income of a business', 'Online sales increased our revenue.', 'Bán hàng trực tuyến làm tăng doanh thu.', 'B2', 'business'),
  ('competitor-noun', 'competitor', 'noun', '/kəmˈpetɪtər/', 'đối thủ cạnh tranh', 'a company that sells similar products', 'Our main competitor lowered its prices.', 'Đối thủ chính của chúng tôi đã giảm giá.', 'B2', 'business'),
  ('leverage-verb', 'leverage', 'verb', '/ˈlevərɪdʒ/', 'tận dụng', 'to use something to get the best result', 'We can leverage social media to reach young customers.', 'Chúng ta có thể tận dụng mạng xã hội để tiếp cận khách hàng trẻ.', 'C1', 'business'),
  ('feasible-adjective', 'feasible', 'adjective', '/ˈfiːzəbəl/', 'khả thi', 'possible and practical to do', 'Is this plan financially feasible?', 'Kế hoạch này có khả thi về tài chính không?', 'C1', 'business'),
  ('borrow-verb', 'borrow', 'verb', '/ˈbɑːroʊ/', 'mượn', 'to take something and promise to return it', 'Can I borrow your pen?', 'Mình mượn bút của bạn được không?', 'A2', 'general'),
  ('suggest-verb', 'suggest', 'verb', '/səɡˈdʒest/', 'gợi ý, đề xuất', 'to mention an idea for someone to consider', 'I suggest we meet on Saturday.', 'Tôi đề xuất chúng ta gặp vào thứ Bảy.', 'B1', 'general'),
  ('however-adverb', 'however', 'adverb', '/haʊˈevər/', 'tuy nhiên', 'used to introduce a contrasting statement', 'The hotel was old. However, it was very clean.', 'Khách sạn cũ. Tuy nhiên, nó rất sạch.', 'B1', 'general'),
  ('although-conjunction', 'although', 'conjunction', '/ɔːlˈðoʊ/', 'mặc dù', 'despite the fact that', 'Although it was raining, we went out.', 'Mặc dù trời mưa, chúng tôi vẫn ra ngoài.', 'B1', 'general'),
  ('therefore-adverb', 'therefore', 'adverb', '/ˈðerfɔːr/', 'vì vậy', 'for that reason', 'The road was closed; therefore, we took a detour.', 'Đường bị chặn, vì vậy chúng tôi đi đường vòng.', 'B2', 'general'),
  ('evaluate-verb', 'evaluate', 'verb', '/ɪˈvæljueɪt/', 'đánh giá', 'to judge the quality or value of something', 'We need to evaluate the results carefully.', 'Chúng ta cần đánh giá kết quả cẩn thận.', 'B2', 'general'),
  ('ambiguous-adjective', 'ambiguous', 'adjective', '/æmˈbɪɡjuəs/', 'mơ hồ, nước đôi', 'having more than one possible meaning', 'The instructions were ambiguous.', 'Hướng dẫn rất mơ hồ.', 'C1', 'general'),
  ('nevertheless-adverb', 'nevertheless', 'adverb', '/ˌnevərðəˈles/', 'tuy vậy, dù sao', 'in spite of what has just been said', 'It was difficult; nevertheless, we finished on time.', 'Việc đó khó; tuy vậy chúng tôi vẫn xong đúng hạn.', 'C1', 'general'),
  ('take-into-account-phrase', 'take into account', 'phrase', '/teɪk ˈɪntuː əˈkaʊnt/', 'tính đến, cân nhắc', 'to consider something when making a decision', 'You should take the cost into account.', 'Bạn nên tính đến chi phí.', 'B2', 'general'),
  ('nuance-noun', 'nuance', 'noun', '/ˈnuːɑːns/', 'sắc thái', 'a very small difference in meaning or feeling', 'Translation often loses the nuance of the original.', 'Bản dịch thường mất đi sắc thái của bản gốc.', 'C2', 'general'),
  ('ubiquitous-adjective', 'ubiquitous', 'adjective', '/juːˈbɪkwɪtəs/', 'có mặt khắp nơi', 'seeming to be everywhere', 'Smartphones are now ubiquitous.', 'Điện thoại thông minh giờ có mặt ở khắp nơi.', 'C2', 'general')
insert into public.lessons (id, kind, level, topic, title, title_vi, summary, content, sort_order) values
  ('present-simple', 'grammar', 'A1', 'tenses', 'Present simple', 'Thì hiện tại đơn', 'Nói về thói quen, sự thật và lịch trình.', '{"explanationVi":"Dùng thì hiện tại đơn để nói về thói quen (I drink coffee every morning), sự thật hiển nhiên (Water boils at 100°C) và lịch trình cố định (The train leaves at 8).\n\nVới chủ ngữ he/she/it, thêm -s hoặc -es vào động từ: work → works, watch → watches, study → studies. Câu phủ định và câu hỏi dùng do/does: She doesn’t like tea. Do you work here?","explanationEn":"Use the present simple for habits, general truths and fixed schedules. Add -s/-es to the verb after he, she or it. Use do/does for negatives and questions.","structure":["I/You/We/They + V","He/She/It + V-s/es","S + do/does + not + V","Do/Does + S + V?"],"examples":[{"en":"She works in a hospital.","vi":"Cô ấy làm việc ở bệnh viện.","correct":true},{"en":"She work in a hospital.","correct":false,"fix":"She works in a hospital.","note":"Chủ ngữ she → động từ thêm -s."},{"en":"Do you live near here?","vi":"Bạn sống gần đây à?","correct":true},{"en":"He don’t like coffee.","correct":false,"fix":"He doesn’t like coffee.","note":"He dùng doesn’t, không dùng don’t."}],"tips":["Trạng từ tần suất (always, usually, often, never) thường đứng trước động từ thường: I usually walk to school."]}'::jsonb, 0),
  ('present-continuous', 'grammar', 'A1', 'tenses', 'Present continuous', 'Thì hiện tại tiếp diễn', 'Hành động đang diễn ra và kế hoạch gần.', '{"explanationVi":"Dùng thì hiện tại tiếp diễn cho hành động đang xảy ra ngay lúc nói (I’m reading now), tình huống tạm thời (She’s staying with her aunt this week) và kế hoạch đã sắp xếp trong tương lai gần (We’re meeting at 6 tonight).\n\nCấu trúc: am/is/are + V-ing. Một số động từ chỉ trạng thái (like, know, want, need) thường không dùng ở dạng tiếp diễn.","explanationEn":"Use am/is/are + -ing for actions happening now, temporary situations and arranged future plans. State verbs such as know, like and want are usually not used in the continuous form.","structure":["S + am/is/are + V-ing","S + am/is/are + not + V-ing","Am/Is/Are + S + V-ing?"],"examples":[{"en":"Look! It’s raining.","vi":"Nhìn kìa! Trời đang mưa.","correct":true},{"en":"I am knowing the answer.","correct":false,"fix":"I know the answer.","note":"“Know” là động từ trạng thái, không dùng tiếp diễn."},{"en":"They are having dinner right now.","vi":"Họ đang ăn tối.","correct":true}],"tips":["Dấu hiệu: now, right now, at the moment, Look!, Listen!"]}'::jsonb, 1),
  ('past-simple', 'grammar', 'A2', 'tenses', 'Past simple', 'Thì quá khứ đơn', 'Hành động đã kết thúc trong quá khứ.', '{"explanationVi":"Dùng thì quá khứ đơn cho hành động đã xảy ra và kết thúc ở một thời điểm xác định trong quá khứ (I visited Hoi An last year).\n\nĐộng từ có quy tắc thêm -ed (work → worked). Động từ bất quy tắc phải học thuộc (go → went, see → saw, buy → bought). Câu phủ định và câu hỏi dùng did + động từ nguyên mẫu: I didn’t go. Did you see it?","explanationEn":"Use the past simple for finished actions at a specific time in the past. Regular verbs add -ed; irregular verbs have special forms. Use did + base verb in negatives and questions.","structure":["S + V-ed / V2","S + did not + V","Did + S + V?"],"examples":[{"en":"We went to the beach yesterday.","vi":"Hôm qua chúng tôi đi biển.","correct":true},{"en":"Did you went to school?","correct":false,"fix":"Did you go to school?","note":"Sau did dùng động từ nguyên mẫu."},{"en":"I bought a new laptop last week.","vi":"Tuần trước tôi mua laptop mới.","correct":true}],"tips":["Dấu hiệu: yesterday, last week/month/year, ago, in 2020."]}'::jsonb, 2),
  ('comparatives-superlatives', 'grammar', 'A2', 'adjectives', 'Comparatives and superlatives', 'So sánh hơn và so sánh nhất', 'So sánh người, vật và địa điểm.', '{"explanationVi":"So sánh hơn: tính từ ngắn thêm -er + than (cheaper than); tính từ dài dùng more + adj + than (more expensive than).\n\nSo sánh nhất: the + adj-est (the cheapest); the most + adj dài (the most expensive). Bất quy tắc: good → better → the best; bad → worse → the worst; far → farther/further.","explanationEn":"Short adjectives take -er/-est; long adjectives use more/most. Good, bad and far are irregular.","structure":["adj-er + than","more + adj + than","the + adj-est","the most + adj"],"examples":[{"en":"Hanoi is colder than Ho Chi Minh City in winter.","vi":"Hà Nội lạnh hơn TP.HCM vào mùa đông.","correct":true},{"en":"This is the more beautiful beach in Vietnam.","correct":false,"fix":"This is the most beautiful beach in Vietnam.","note":"So sánh nhất dùng the most."},{"en":"My English is better than last year.","vi":"Tiếng Anh của tôi tốt hơn năm ngoái.","correct":true}],"tips":["Tính từ hai âm tiết tận cùng -y: happy → happier → the happiest."]}'::jsonb, 3),
  ('present-perfect', 'grammar', 'B1', 'tenses', 'Present perfect', 'Thì hiện tại hoàn thành', 'Kinh nghiệm, kết quả hiện tại, hành động kéo dài đến nay.', '{"explanationVi":"Dùng thì hiện tại hoàn thành (have/has + V3) khi:\n• nói về kinh nghiệm mà không nêu thời điểm (I have been to Japan);\n• hành động vừa xảy ra còn kết quả ở hiện tại (I’ve lost my keys — giờ vẫn chưa tìm thấy);\n• hành động bắt đầu trong quá khứ và kéo dài đến nay với for/since (She has worked here since 2021).\n\nKhông dùng với mốc thời gian quá khứ cụ thể (yesterday, last year) — khi đó dùng quá khứ đơn.","explanationEn":"Use have/has + past participle for experiences, recent actions with present results, and situations continuing up to now (for/since). Do not use it with a finished past time like yesterday.","structure":["S + have/has + V3","S + have/has + not + V3","Have/Has + S + V3?"],"examples":[{"en":"I have never tried durian.","vi":"Tôi chưa bao giờ ăn thử sầu riêng.","correct":true},{"en":"I have seen that film yesterday.","correct":false,"fix":"I saw that film yesterday.","note":"“Yesterday” là thời điểm quá khứ cụ thể → quá khứ đơn."},{"en":"They have lived here for ten years.","vi":"Họ đã sống ở đây mười năm.","correct":true}],"tips":["for + khoảng thời gian (for two years); since + mốc thời gian (since 2020, since Monday)."]}'::jsonb, 4),
  ('conditionals-first-second', 'grammar', 'B1', 'conditionals', 'First and second conditionals', 'Câu điều kiện loại 1 và loại 2', 'Khả năng có thật và tình huống giả định.', '{"explanationVi":"Loại 1 — điều có thể xảy ra ở hiện tại/tương lai: If + hiện tại đơn, will + V. (If it rains, we will stay home.)\n\nLoại 2 — tình huống giả định, không có thật hoặc khó xảy ra ở hiện tại: If + quá khứ đơn, would + V. (If I had more time, I would learn Japanese.) Với “be” ở loại 2, dùng were cho mọi ngôi trong văn phong trang trọng: If I were you, …","explanationEn":"First conditional: real possibility (if + present, will + verb). Second conditional: imaginary or unlikely situations (if + past, would + verb).","structure":["If + present simple, will + V","If + past simple, would + V"],"examples":[{"en":"If you study hard, you will pass.","vi":"Nếu bạn học chăm, bạn sẽ đậu.","correct":true},{"en":"If I will see him, I will tell him.","correct":false,"fix":"If I see him, I will tell him.","note":"Mệnh đề if không dùng will."},{"en":"If I were rich, I would travel the world.","vi":"Nếu tôi giàu, tôi sẽ đi du lịch khắp thế giới.","correct":true}],"tips":["Có thể đảo mệnh đề: We will stay home if it rains (không cần dấu phẩy)."]}'::jsonb, 5),
  ('passive-voice', 'grammar', 'B1', 'voice', 'The passive voice', 'Câu bị động', 'Nhấn mạnh hành động hoặc đối tượng chịu tác động.', '{"explanationVi":"Câu bị động dùng khi người thực hiện không quan trọng, không rõ, hoặc khi muốn nhấn mạnh đối tượng: be + V3 (past participle).\n\nVí dụ: People speak English here → English is spoken here. Hiện tại: is/are + V3; quá khứ: was/were + V3; hiện tại hoàn thành: has/have been + V3; tương lai: will be + V3. Muốn nêu người thực hiện, dùng by: The book was written by a Vietnamese author.","explanationEn":"Form the passive with be + past participle. Use it when the doer is unknown, unimportant or obvious. Add “by + agent” only when useful.","structure":["S + am/is/are + V3","S + was/were + V3","S + has/have been + V3","S + will be + V3"],"examples":[{"en":"The bridge was built in 1990.","vi":"Cây cầu được xây năm 1990.","correct":true},{"en":"The emails are send every morning.","correct":false,"fix":"The emails are sent every morning.","note":"Bị động dùng V3: sent."},{"en":"Your order has been shipped.","vi":"Đơn hàng của bạn đã được gửi đi.","correct":true}],"tips":["Văn bản trang trọng, khoa học, tin tức thường dùng nhiều câu bị động."]}'::jsonb, 6),
  ('reported-speech', 'grammar', 'B2', 'reporting', 'Reported speech', 'Câu tường thuật', 'Thuật lại lời người khác nói.', '{"explanationVi":"Khi thuật lại lời nói với động từ tường thuật ở quá khứ (said, told), ta thường lùi thì: hiện tại đơn → quá khứ đơn; hiện tại tiếp diễn → quá khứ tiếp diễn; quá khứ đơn/hiện tại hoàn thành → quá khứ hoàn thành; will → would; can → could.\n\nĐổi đại từ và trạng từ cho phù hợp: today → that day, tomorrow → the next day, here → there. “Tell” cần tân ngữ (He told me…), “say” thì không (He said…). Câu hỏi tường thuật dùng trật tự câu khẳng định: She asked where I lived.","explanationEn":"After a past reporting verb, tenses usually move back one step and pronouns/time words change. Tell takes an object; say does not. Reported questions use statement word order.","structure":["S + said (that) + clause (backshift)","S + told + O + (that) + clause","S + asked + (O) + if/wh- + S + V"],"examples":[{"en":"“I’m tired.” → She said she was tired.","correct":true,"vi":"Cô ấy nói rằng cô ấy mệt."},{"en":"He said me that he was busy.","correct":false,"fix":"He told me that he was busy.","note":"Có tân ngữ “me” → dùng told."},{"en":"She asked me where did I live.","correct":false,"fix":"She asked me where I lived.","note":"Câu hỏi tường thuật không đảo ngữ."}],"tips":["Nếu điều được nói vẫn đúng ở hiện tại, có thể không lùi thì: He said he lives in Hanoi."]}'::jsonb, 7),
  ('relative-clauses', 'grammar', 'B2', 'clauses', 'Relative clauses', 'Mệnh đề quan hệ', 'Nối câu và bổ sung thông tin cho danh từ.', '{"explanationVi":"Mệnh đề quan hệ bổ sung thông tin cho danh từ đứng trước. Dùng who cho người, which cho vật, that cho cả hai (trong mệnh đề xác định), whose chỉ sở hữu, where cho nơi chốn.\n\nMệnh đề xác định (không dấu phẩy) cho biết “cái nào”: The man who lives next door is a doctor. Mệnh đề không xác định (có dấu phẩy) chỉ thêm thông tin, không dùng that: My mother, who is 60, still runs every day.","explanationEn":"Use who (people), which (things), that (people or things, defining only), whose (possession) and where (places). Non-defining clauses take commas and never use that.","structure":["N + who/which/that + V…","N + whose + N…","N + where + S + V…"],"examples":[{"en":"The app that I use every day is free.","vi":"Ứng dụng tôi dùng hằng ngày là miễn phí.","correct":true},{"en":"Hanoi, that is the capital, is busy.","correct":false,"fix":"Hanoi, which is the capital, is busy.","note":"Mệnh đề không xác định không dùng that."},{"en":"That’s the café where we first met.","vi":"Đó là quán cà phê nơi chúng ta gặp nhau lần đầu.","correct":true}],"tips":["Trong mệnh đề xác định, có thể lược who/which/that khi nó là tân ngữ: The book (that) I read was great."]}'::jsonb, 8),
  ('modals-deduction', 'grammar', 'B2', 'modals', 'Modals of deduction', 'Động từ khuyết thiếu chỉ suy đoán', 'must, might, can’t — đoán mức độ chắc chắn.', '{"explanationVi":"Dùng động từ khuyết thiếu để suy đoán dựa trên bằng chứng:\n• must: gần như chắc chắn đúng (She must be tired — cô ấy làm việc 12 tiếng);\n• might / may / could: có thể (He might be at the gym);\n• can’t: gần như chắc chắn sai (That can’t be true).\n\nSuy đoán về quá khứ: modal + have + V3 (They must have left early. She can’t have seen us.)","explanationEn":"must = almost certain, might/may/could = possible, can’t = almost certainly not. For the past use modal + have + past participle.","structure":["must / might / can’t + V","must / might / can’t + have + V3"],"examples":[{"en":"The lights are off. They must be asleep.","vi":"Đèn tắt rồi. Chắc họ ngủ rồi.","correct":true},{"en":"He mustn’t be at home; his car isn’t there.","correct":false,"fix":"He can’t be at home; his car isn’t there.","note":"Suy đoán phủ định dùng can’t, không dùng mustn’t."},{"en":"She might have missed the bus.","vi":"Có thể cô ấy lỡ xe buýt.","correct":true}],"tips":["“Mustn’t” nghĩa là “cấm”, không dùng để suy đoán."]}'::jsonb, 9),
  ('inversion-emphasis', 'grammar', 'C1', 'advanced', 'Inversion for emphasis', 'Đảo ngữ để nhấn mạnh', 'Never have I…, Not only… but also…', '{"explanationVi":"Trong văn phong trang trọng, khi đặt trạng từ phủ định hoặc hạn chế ở đầu câu (never, rarely, seldom, not only, no sooner, hardly, little, under no circumstances), ta đảo trợ động từ lên trước chủ ngữ.\n\nVí dụ: I have never seen such a view → Never have I seen such a view. She not only sings but also writes songs → Not only does she sing, but she also writes songs.","explanationEn":"After negative or restrictive adverbials at the start of a clause, invert the auxiliary and subject. This is typical of formal writing and speeches.","structure":["Never/Rarely/Seldom + aux + S + V","Not only + aux + S + V, but S + also + V","No sooner + had + S + V3 + than…"],"examples":[{"en":"Rarely do we see such dedication.","vi":"Hiếm khi chúng ta thấy sự tận tâm như vậy.","correct":true},{"en":"Never I have been so surprised.","correct":false,"fix":"Never have I been so surprised.","note":"Đảo trợ động từ “have” lên trước chủ ngữ."},{"en":"No sooner had we arrived than it started to rain.","vi":"Chúng tôi vừa đến thì trời đổ mưa.","correct":true}],"tips":["Không lạm dụng trong hội thoại thân mật — nghe sẽ rất trang trọng."]}'::jsonb, 10),
  ('reading-my-neighborhood', 'reading', 'A1', 'daily_life', 'My neighborhood', 'Khu phố của tôi', 'Một người kể về khu phố nơi mình sống.', '{"passage":"My name is Lan and I live in a small street in Da Nang. My street is quiet in the morning and busy in the evening.\n\nNext to my house, there is a bakery. The bread is fresh and cheap, so I buy it every morning. Across the street, there is a small park with tall trees. Old people do exercise there at six o’clock, and children play football after school.\n\nMy favorite place is the café at the end of the street. The owner, Mr. Minh, is very friendly. I often sit there on Sunday and read a book. I love my neighborhood because the people are kind and everything is near.","summaryVi":"Lan sống ở một con phố nhỏ tại Đà Nẵng, có tiệm bánh mì, công viên và quán cà phê cô yêu thích. Cô yêu khu phố vì mọi người tốt bụng và mọi thứ đều gần.","wordCount":113}'::jsonb, 0),
  ('reading-weekend-trip', 'reading', 'A2', 'travel', 'A weekend in Hoi An', 'Cuối tuần ở Hội An', 'Chuyến đi cuối tuần của hai người bạn.', '{"passage":"Last weekend, my friend Huy and I took the bus to Hoi An. The trip took only one hour, and the tickets were cheap.\n\nWe stayed in a small homestay near the river. On Saturday morning, we rented bicycles and rode to An Bang Beach. The water was warm and clean, but the sun was very strong, so we didn’t stay long.\n\nIn the evening, the old town was beautiful. Hundreds of lanterns were glowing, and many tourists were taking photos. We tried cao lầu, a famous local noodle dish, and bought some handmade souvenirs for our families.\n\nOn Sunday, it rained all morning. We spent the time in a café and talked about our next trip. Huy wants to visit Ha Giang, but I prefer the beach. Maybe we will go to both!","summaryVi":"Hai người bạn đi Hội An bằng xe buýt, đạp xe ra biển An Bàng, ngắm phố cổ đèn lồng, ăn cao lầu và mua quà. Chủ nhật trời mưa nên họ ngồi cà phê bàn chuyến đi tiếp theo.","wordCount":134}'::jsonb, 1),
  ('reading-remote-work', 'reading', 'B1', 'work', 'Working from home: pros and cons', 'Làm việc tại nhà: ưu và nhược điểm', 'Lợi ích và thách thức của làm việc từ xa.', '{"passage":"Since 2020, many companies have allowed their employees to work from home for at least part of the week. For a lot of people, this change has been positive. They no longer spend an hour or more commuting, so they have more time for family, exercise or sleep. Some workers also say they can concentrate better at home because the office is noisy.\n\nHowever, working from home is not perfect. Many people find it hard to separate work from personal life. When your laptop is always on the kitchen table, it is tempting to answer emails late at night. Others feel lonely because they miss chatting with colleagues over lunch. New employees may also learn more slowly, since they cannot easily watch and ask experienced coworkers.\n\nAs a result, a growing number of companies are choosing a hybrid model. Employees work in the office two or three days a week for meetings and teamwork, and stay at home on the other days for focused tasks. The key, according to most experts, is clear communication: teams need to agree on when people are available and how quickly they should reply.","summaryVi":"Làm việc tại nhà giúp tiết kiệm thời gian đi lại và tập trung hơn, nhưng dễ lẫn lộn công việc với đời sống, gây cô đơn và khiến nhân viên mới học chậm. Nhiều công ty chọn mô hình kết hợp; điều quan trọng là giao tiếp rõ ràng.","wordCount":189}'::jsonb, 2),
  ('reading-plastic-ocean', 'reading', 'B2', 'environment', 'Can we stop plastic from reaching the ocean?', 'Có thể ngăn nhựa ra biển không?', 'Nguyên nhân và giải pháp cho rác nhựa đại dương.', '{"passage":"Every year, millions of tonnes of plastic waste end up in the world’s oceans. Much of it does not come from ships or beaches, but from rivers that carry rubbish from cities far inland. Once in the sea, plastic breaks down into tiny pieces known as microplastics, which are eaten by fish and eventually find their way into the food we eat.\n\nGovernments have tried a range of measures. Some have banned single-use plastic bags or introduced a small charge for them, which in several countries has reduced their use dramatically. Others are investing in better waste collection, since a large proportion of ocean plastic comes from places where rubbish is simply not collected at all.\n\nTechnology also plays a role. Floating barriers placed at river mouths can catch waste before it reaches the sea, and researchers are developing materials that break down more safely. Nevertheless, most scientists agree that clean-up alone cannot solve the problem. As one researcher put it, “If your bathtub is overflowing, you don’t start by mopping the floor — you turn off the tap.” In other words, the most effective solution is to produce and throw away less plastic in the first place.","summaryVi":"Rác nhựa ra biển chủ yếu qua các con sông, phân rã thành vi nhựa đi vào chuỗi thức ăn. Lệnh cấm túi nilon, thu gom rác tốt hơn và công nghệ đều giúp ích, nhưng giải pháp hiệu quả nhất là giảm sản xuất và thải bỏ nhựa ngay từ đầu.","wordCount":198}'::jsonb, 3),
  ('reading-attention-economy', 'reading', 'C1', 'technology', 'The attention economy', 'Nền kinh tế chú ý', 'Ứng dụng được thiết kế để giữ chân người dùng như thế nào.', '{"passage":"Many of the apps on our phones are free, yet the companies behind them are among the most valuable in the world. The apparent paradox disappears once we recognise what is actually being sold: our attention. The longer we scroll, watch and tap, the more advertising can be shown to us, and the more data is gathered about our habits.\n\nTo maximise this engagement, designers draw on insights from behavioural psychology. Infinite feeds remove natural stopping points; unpredictable rewards, such as the occasional notification of a “like”, keep us checking our screens in much the same way that slot machines keep gamblers pulling the lever. None of these features is inherently sinister, but taken together they create an environment in which putting the phone down requires a conscious effort.\n\nCritics argue that this business model has hidden costs, from shorter attention spans to the spread of sensational content, which tends to attract more clicks than careful reporting. Defenders reply that users are free to leave and that personalised feeds genuinely help people discover things they enjoy. What is beyond dispute is that our attention is finite. Deciding deliberately where to spend it — rather than letting an algorithm decide for us — may be one of the more important skills of the digital age.","summaryVi":"Ứng dụng miễn phí kiếm tiền từ sự chú ý của người dùng. Các kỹ thuật như bảng tin vô tận và phần thưởng bất ngờ khiến ta khó rời điện thoại. Có tranh luận về tác hại và lợi ích, nhưng chắc chắn rằng sự chú ý là hữu hạn và cần được sử dụng có chủ đích.","wordCount":214}'::jsonb, 4),
  ('listening-cafe-order', 'listening', 'A1', 'food', 'At the café', 'Ở quán cà phê', 'Gọi đồ uống và bánh ở quán cà phê.', '{"script":[{"speaker":"Barista","text":"Hi there! What can I get for you?"},{"speaker":"Customer","text":"Hello. Can I have a large iced coffee, please?"},{"speaker":"Barista","text":"Sure. With milk or without milk?"},{"speaker":"Customer","text":"With milk, please. And one chocolate muffin."},{"speaker":"Barista","text":"Is that for here or to go?"},{"speaker":"Customer","text":"For here, thanks."},{"speaker":"Barista","text":"Okay. That’s six dollars and fifty cents."},{"speaker":"Customer","text":"Here you are."}],"summaryVi":"Khách gọi một ly cà phê sữa đá lớn và một bánh muffin sô-cô-la, dùng tại chỗ, tổng cộng 6,50 đô.","dictation":["Can I have a large iced coffee, please?","Is that for here or to go?"]}'::jsonb, 0),
  ('listening-directions', 'listening', 'A2', 'travel', 'Finding the museum', 'Tìm đường đến bảo tàng', 'Một du khách hỏi đường đến bảo tàng.', '{"script":[{"speaker":"Tourist","text":"Excuse me, could you tell me how to get to the history museum?"},{"speaker":"Local","text":"Of course. Go straight down this street until you reach the traffic lights."},{"speaker":"Local","text":"Then turn left. The museum is on the right, opposite a big bookstore."},{"speaker":"Tourist","text":"Is it far from here?"},{"speaker":"Local","text":"Not really. It’s about a ten-minute walk."},{"speaker":"Tourist","text":"Great. Do you know what time it closes?"},{"speaker":"Local","text":"I think it closes at five, but it’s closed on Mondays."},{"speaker":"Tourist","text":"Thank you so much!"}],"summaryVi":"Đi thẳng tới đèn giao thông, rẽ trái, bảo tàng ở bên phải đối diện hiệu sách lớn; đi bộ khoảng mười phút; đóng cửa lúc 5 giờ và nghỉ thứ Hai.","dictation":["Go straight down this street until you reach the traffic lights.","It’s about a ten-minute walk."]}'::jsonb, 1),
  ('listening-job-call', 'listening', 'B1', 'work', 'A call about a job interview', 'Cuộc gọi hẹn phỏng vấn', 'Nhân sự gọi điện sắp xếp lịch phỏng vấn.', '{"script":[{"speaker":"Recruiter","text":"Hello, is this Nam? This is Sarah from Bright Solutions. You applied for our junior designer position."},{"speaker":"Nam","text":"Yes, hi Sarah. Thanks for calling."},{"speaker":"Recruiter","text":"We liked your portfolio, and we’d like to invite you to an interview. Are you available on Thursday morning?"},{"speaker":"Nam","text":"Thursday morning is a bit difficult because I have a class. Would Thursday afternoon work?"},{"speaker":"Recruiter","text":"Let me check. Yes, we could do two thirty. The interview will take about forty-five minutes."},{"speaker":"Nam","text":"Perfect. Should I bring anything?"},{"speaker":"Recruiter","text":"Please bring a laptop so you can present two of your recent projects. I’ll send the address by email today."},{"speaker":"Nam","text":"Great, I’ll look out for it. Thank you!"}],"summaryVi":"Nam được mời phỏng vấn vị trí nhà thiết kế. Vì buổi sáng có lớp, lịch được chuyển sang 2:30 chiều thứ Năm, kéo dài khoảng 45 phút; Nam cần mang laptop để trình bày hai dự án.","dictation":["We would like to invite you to an interview.","I will send the address by email today."]}'::jsonb, 2),
  ('listening-sleep-podcast', 'listening', 'B2', 'health', 'Podcast: why sleep matters', 'Podcast: vì sao giấc ngủ quan trọng', 'Một đoạn podcast ngắn về giấc ngủ.', '{"script":[{"speaker":"Host","text":"Welcome back to Healthy Minutes. Today we’re talking about something we all do, but rarely think about: sleep."},{"speaker":"Host","text":"Most adults need between seven and nine hours a night, yet surveys suggest that around a third of us regularly get less than that."},{"speaker":"Host","text":"Lack of sleep doesn’t just make you tired. It affects your memory, your mood and even your immune system, which is why you may catch colds more easily after a stressful week."},{"speaker":"Host","text":"So what can you do? First, try to go to bed and wake up at the same time every day, even at weekends."},{"speaker":"Host","text":"Second, keep your bedroom cool and dark, and avoid bright screens for an hour before bed."},{"speaker":"Host","text":"And finally, watch your caffeine. A coffee at four in the afternoon can still be affecting you at midnight."}],"summaryVi":"Người lớn cần 7–9 tiếng ngủ; thiếu ngủ ảnh hưởng trí nhớ, tâm trạng và hệ miễn dịch. Lời khuyên: ngủ dậy đúng giờ, phòng mát và tối, tránh màn hình trước khi ngủ, hạn chế caffeine buổi chiều.","dictation":["Most adults need between seven and nine hours a night.","Keep your bedroom cool and dark."]}'::jsonb, 3),
  ('listening-city-lecture', 'listening', 'C1', 'environment', 'Lecture excerpt: designing cooler cities', 'Trích bài giảng: thiết kế thành phố mát hơn', 'Hiệu ứng đảo nhiệt đô thị và giải pháp.', '{"script":[{"speaker":"Lecturer","text":"Let’s turn to what’s known as the urban heat island effect. On a summer evening, the centre of a large city can be several degrees warmer than the surrounding countryside."},{"speaker":"Lecturer","text":"The reasons are fairly well understood. Dark surfaces such as asphalt absorb heat during the day and release it slowly at night, while air conditioners pump even more warm air into the streets."},{"speaker":"Lecturer","text":"What’s encouraging is that relatively simple interventions can make a measurable difference. Planting street trees provides shade and cools the air through evaporation."},{"speaker":"Lecturer","text":"Painting roofs in light colours reflects sunlight rather than absorbing it, and some cities now require new buildings to include green roofs."},{"speaker":"Lecturer","text":"The challenge, of course, is that these measures are often introduced in wealthier neighbourhoods first, whereas the hottest districts tend to be the poorest. So the question isn’t only technical; it’s also about fairness."}],"summaryVi":"Trung tâm thành phố nóng hơn vùng quê do bề mặt tối màu hấp thụ nhiệt và máy lạnh thải khí nóng. Cây xanh, mái nhà sáng màu và mái xanh giúp làm mát, nhưng thường được áp dụng ở khu giàu trước, đặt ra vấn đề công bằng.","dictation":["Dark surfaces such as asphalt absorb heat during the day.","The question is not only technical; it is also about fairness."]}'::jsonb, 4),
  ('pron-th-sounds', 'pronunciation', 'A2', 'consonants', 'TH sounds /θ/ and /ð/', 'Âm TH /θ/ và /ð/', 'Người Việt hay đọc “th” thành /t/ hoặc /d/.', '{"tipsVi":"Đặt nhẹ đầu lưỡi giữa hai hàm răng và thổi hơi ra. /θ/ (think) không rung dây thanh; /ð/ (this) có rung. Đừng đọc “think” thành “tink”.","sentences":[{"text":"I think this is the third time."},{"text":"Thank you for everything."},{"text":"My brother and father are both there."},{"text":"They threw the ball through the window."}]}'::jsonb, 0),
  ('pron-final-sounds', 'pronunciation', 'A2', 'consonants', 'Final consonants', 'Âm cuối', 'Đọc rõ âm cuối /s/, /t/, /d/, /k/.', '{"tipsVi":"Tiếng Việt ít âm cuối bật hơi nên người học hay bỏ âm cuối (“like” thành “lai”). Hãy kết thúc từ dứt khoát, đặc biệt với -s số nhiều và -ed quá khứ.","sentences":[{"text":"She likes cats and dogs."},{"text":"I walked to the market and bought some fruit."},{"text":"He asked for six books."},{"text":"The kids played outside last weekend."}]}'::jsonb, 1),
  ('pron-ed-endings', 'pronunciation', 'B1', 'endings', '-ed endings: /t/, /d/, /ɪd/', 'Đuôi -ed: /t/, /d/, /ɪd/', 'Ba cách đọc đuôi -ed.', '{"tipsVi":"/ɪd/ sau âm /t/, /d/ (wanted, needed); /t/ sau âm vô thanh /p, k, s, ʃ, tʃ, f/ (stopped, watched); /d/ trong các trường hợp còn lại (played, cleaned).","sentences":[{"text":"We wanted to visit, but we needed more time."},{"text":"She watched a film and laughed a lot."},{"text":"They cleaned the room and opened the windows."},{"text":"I decided to start again."}]}'::jsonb, 2),
  ('pron-word-stress', 'pronunciation', 'B1', 'stress', 'Word stress', 'Trọng âm từ', 'Nhấn đúng âm tiết giúp người nghe hiểu bạn.', '{"tipsVi":"Nhiều danh từ hai âm tiết nhấn âm đầu (PREsent, REcord), động từ nhấn âm sau (preSENT, reCORD). Từ có đuôi -tion nhấn âm ngay trước nó (eduCAtion, inforMAtion).","sentences":[{"text":"I want to present my present to the teacher."},{"text":"Education is important for every generation."},{"text":"The photographer took a beautiful photograph."},{"text":"Please record the meeting for our records."}]}'::jsonb, 3),
  ('pron-linking', 'pronunciation', 'B2', 'connected_speech', 'Linking and connected speech', 'Nối âm', 'Nói tự nhiên hơn bằng cách nối âm.', '{"tipsVi":"Khi một từ kết thúc bằng phụ âm và từ sau bắt đầu bằng nguyên âm, hãy nối lại: “pick it up” → /pɪ-kɪ-tʌp/. Đừng ngắt quãng từng từ.","sentences":[{"text":"Pick it up and put it on the table."},{"text":"Can I have an apple, please?"},{"text":"Turn off the lights when you leave."},{"text":"What are you up to this evening?"}]}'::jsonb, 4)
insert into public.exercises (id, lesson_id, type, level, prompt, data, answer, explanation_vi, sort_order) values
  ('present-simple-1', 'present-simple', 'multiple_choice', 'A1', 'My brother ___ football every Sunday.', '{"options":["play","plays","playing","is play"]}'::jsonb, '{"index":1}'::jsonb, 'Chủ ngữ “my brother” là ngôi thứ ba số ít → plays.', 0),
  ('present-simple-2', 'present-simple', 'fill_blank', 'A1', 'She ___ (watch) TV in the evening.', '{}'::jsonb, '{"accepted":["watches"]}'::jsonb, 'Động từ tận cùng -ch thêm -es: watches.', 1),
  ('present-simple-3', 'present-simple', 'multiple_choice', 'A1', '___ your parents speak English?', '{"options":["Does","Do","Are","Is"]}'::jsonb, '{"index":1}'::jsonb, '“Your parents” là số nhiều → Do.', 2),
  ('present-simple-4', 'present-simple', 'reorder', 'A1', 'Sắp xếp các từ thành câu đúng.', '{"tokens":["never","eats","meat","He"]}'::jsonb, '{"sentence":"He never eats meat"}'::jsonb, 'Trạng từ tần suất đứng trước động từ thường.', 3),
  ('present-simple-5', 'present-simple', 'error_correction', 'A1', 'My sister study English every day.', '{}'::jsonb, '{"accepted":["My sister studies English every day.","My sister studies English every day"]}'::jsonb, 'study → studies (phụ âm + y → ies).', 4),
  ('present-simple-6', 'present-simple', 'fill_blank', 'A1', 'We ___ (not / work) on Sundays.', '{}'::jsonb, '{"accepted":["don''t work","do not work","don’t work"]}'::jsonb, 'We + don’t + V.', 5),
  ('present-continuous-1', 'present-continuous', 'multiple_choice', 'A1', 'Listen! Someone ___ at the door.', '{"options":["knocks","is knocking","knock","knocked"]}'::jsonb, '{"index":1}'::jsonb, '“Listen!” → hành động đang xảy ra.', 0),
  ('present-continuous-2', 'present-continuous', 'fill_blank', 'A1', 'I ___ (cook) dinner at the moment.', '{}'::jsonb, '{"accepted":["am cooking","i''m cooking","I’m cooking"]}'::jsonb, 'I + am + V-ing.', 1),
  ('present-continuous-3', 'present-continuous', 'reorder', 'A1', 'Sắp xếp các từ thành câu đúng.', '{"tokens":["are","what","doing","you"]}'::jsonb, '{"sentence":"what are you doing"}'::jsonb, 'Từ để hỏi + are + S + V-ing.', 2),
  ('present-continuous-4', 'present-continuous', 'error_correction', 'A1', 'She is wanting a new phone.', '{}'::jsonb, '{"accepted":["She wants a new phone.","She wants a new phone"]}'::jsonb, '“Want” là động từ trạng thái → dùng hiện tại đơn.', 3),
  ('present-continuous-5', 'present-continuous', 'multiple_choice', 'A1', 'We ___ my grandparents this weekend. It’s all arranged.', '{"options":["visit","are visiting","visited","were visiting"]}'::jsonb, '{"index":1}'::jsonb, 'Kế hoạch đã sắp xếp → hiện tại tiếp diễn.', 4),
